input.command:
cat << 'EOF' | node -e "
const fs = require('fs');

// Read the .env.test file
const content = fs.readFileSync('/tmp/p15-test-WdsMaG/.env.test', 'utf8');

// Parse environment variables, skipping comments and empty lines
const envVars = {};
content.split('\n').forEach(line => {
  line = line.trim();
  if (!line || line.startsWith('#')) return;
  const parts = line.split('=');
  if (parts.length >= 2) {
    envVars[parts[0]] = parts.slice(1).join('=');
  }
});

console.log(JSON.stringify(envVars, null, 2));
"
EOF

